import 'dart:convert';

import 'package:flutter/material.dart';

// HIER DEINEN KOPIERTEN DATA-URI-TEXT EINSETZEN (z. B. 'data:image/jpeg;base64,/9j/4AAQ...')
const String planBase64 =
    'data:image/jpeg;base64,';

void main() {
  runApp(const MelderApp());
}

class MelderApp extends StatelessWidget {
  const MelderApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Brandschutzplan-Finder',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        primarySwatch: Colors.red,
        useMaterial3: true,
      ),
      home: const PlanScreen(),
    );
  }
}

class Melder {
  final String nummer;
  final double x;
  final double y;

  Melder({required this.nummer, required this.x, required this.y});
}

class PlanScreen extends StatefulWidget {
  const PlanScreen({super.key});

  @override
  State<PlanScreen> createState() => _PlanScreenState();
}

class _PlanScreenState extends State<PlanScreen> {
  // Hier fügst du die aus der Konsole kopierten Melder ein:
  final List<Melder> _melderListe = [
    Melder(nummer: '24/2', x: 0.552, y: 0.725),
    Melder(nummer: '24/3', x: 0.535, y: 0.725),
    Melder(nummer: '24/4', x: 0.513, y: 0.725),
    Melder(nummer: '24/5', x: 0.503, y: 0.725),
    Melder(nummer: '24/6', x: 0.495, y: 0.725),

  ];
  String _searchQuery = '';
  bool _adminMode = false;

  final TransformationController _transformationController = TransformationController();
  final TextEditingController _searchController = TextEditingController();

  void _addMelder(Offset tapPosition, Size imageSize) {
    final double relX = tapPosition.dx / imageSize.width;
    final double relY = tapPosition.dy / imageSize.height;
    final TextEditingController numController = TextEditingController();

    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: const Text('Melder einmessen'),
        content: TextField(
          controller: numController,
          autofocus: true,
          decoration: const InputDecoration(
            labelText: 'Meldernummer (z. B. 57/6)',
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Abbrechen'),
          ),
          ElevatedButton(
            onPressed: () {
              if (numController.text.trim().isNotEmpty) {
                final String melderNummer = numController.text.trim();

                // 1. In die laufende Ansicht übernehmen
                setState(() {
                  _melderListe.add(Melder(
                    nummer: melderNummer,
                    x: relX,
                    y: relY,
                  ));
                });

                // 2. INTEGRATION WEG 1: Druckt den fertigen Code in die Konsole
                print("Melder(nummer: '$melderNummer', x: ${relX.toStringAsFixed(3)}, y: ${relY.toStringAsFixed(3)}),");

                Navigator.pop(context);
              }
            },
            child: const Text('Speichern'),
          ),
        ],
      ),
    );
  }

  // Präziser Zoom in die Bildmitte basierend auf der echten Anzeigegröße
  void _zoomToMelder(Melder melder, Size displaySize) {
    final double targetX = melder.x * displaySize.width;
    final double targetY = melder.y * displaySize.height;
    const double zoomLevel = 4.0; // Zoomfaktor beim Suchen

    final double translateX = (displaySize.width / 2) - (targetX * zoomLevel);
    final double translateY = (displaySize.height / 2) - (targetY * zoomLevel);

    final Matrix4 matrix = Matrix4.identity()
      ..translate(translateX, translateY)
      ..scale(zoomLevel);

    setState(() {
      _transformationController.value = matrix;
      _searchQuery = melder.nummer;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Brandschutzplan-Finder'),
        actions: [
          Row(
            children: [
              Text(_adminMode ? 'Einmessen' : 'Suchen', style: const TextStyle(fontSize: 12)),
              Switch(
                value: _adminMode,
                onChanged: (val) => setState(() => _adminMode = val),
              ),
            ],
          )
        ],
      ),
      body: LayoutBuilder(
        builder: (context, constraints) {
          final Size planSize = Size(constraints.maxWidth, constraints.maxHeight - 65);

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.all(8.0),
                child: Row(
                  children: [
                    Expanded(
                      child: TextField(
                        controller: _searchController,
                        decoration: const InputDecoration(
                          labelText: 'Meldernummer eingeben',
                          border: OutlineInputBorder(),
                          suffixIcon: Icon(Icons.search),
                        ),
                        onSubmitted: (val) {
                          final match = _melderListe.firstWhere(
                            (m) => m.nummer.toLowerCase() == val.trim().toLowerCase(),
                            orElse: () => Melder(nummer: '', x: 0, y: 0),
                          );
                          if (match.nummer.isNotEmpty) {
                            _zoomToMelder(match, planSize);
                          } else {
                            ScaffoldMessenger.of(context).showSnackBar(
                              const SnackBar(content: Text('Melder nicht gefunden!')),
                            );
                          }
                        },
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: InteractiveViewer(
                  transformationController: _transformationController,
                  minScale: 1.0,
                  maxScale: 30.0,
                  child: GestureDetector(
                    onTapUp: (details) {
                      if (_adminMode) {
                        _addMelder(details.localPosition, planSize);
                      }
                    },
                    child: Stack(
                      children: [
                        // BASE64-PLAN-DECODER
                        Builder(
                          builder: (context) {
                            try {
                              final String bytesString = planBase64.contains(',')
                                  ? planBase64.split(',').last
                                  : planBase64;
                              return Image.memory(
                                base64Decode(bytesString),
                                width: planSize.width,
                                height: planSize.height,
                                fit: BoxFit.contain,
                                errorBuilder: (context, error, stackTrace) => Container(
                                  color: Colors.grey[300],
                                  child: const Center(
                                    child: Text('Fehler beim Laden des Base64-Bildes'),
                                  ),
                                ),
                              );
                            } catch (e) {
                              return Container(
                                color: Colors.grey[300],
                                child: const Center(
                                  child: Text('Füge deinen kopierten Base64-Text in Zeile 5 ein'),
                                ),
                              );
                            }
                          },
                        ),

                        // PINS AUF DEM PLAN
                        ..._melderListe.map((melder) {
                          final isSelected = melder.nummer.toLowerCase() == _searchQuery.toLowerCase();
                          final double pinSize = isSelected ? 10.0 : 5.0;

                          return Positioned(
                            left: (melder.x * planSize.width) - (pinSize / 2),
                            top: (melder.y * planSize.height) - (pinSize / 2),
                            child: GestureDetector(
                              onTap: () {
                                setState(() {
                                  _searchQuery = melder.nummer;
                                  _searchController.text = melder.nummer;
                                });
                              },
                              child: Container(
                                width: pinSize,
                                height: pinSize,
                                decoration: BoxDecoration(
                                  color: isSelected ? Colors.red : Colors.blue.withOpacity(0.8),
                                  shape: BoxShape.circle,
                                  border: Border.all(color: Colors.white, width: isSelected ? 0.3 : 0.1),
                                  boxShadow: isSelected
                                      ? [const BoxShadow(color: Colors.redAccent, blurRadius: 10, spreadRadius: 2)]
                                      : [],
                                ),
                                child: Center(
                                  child: Text(
                                    melder.nummer,
                                    style: TextStyle(
                                      color: Colors.white,
                                      fontSize: isSelected ? 3 : 1.4,
                                      fontWeight: FontWeight.bold,
                                    ),
                                  ),
                                ),
                              ),
                            ),
                          );
                        }),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}
